/** Older names for a drawing above: still drawn, not offered. */
const DECK_ICON_ALIASES: Readonly<Record<string, string>> = {
  "checkmark-filled": "checkmark-outline",
  lightning: "flash",
  "star-filled": "star",
  "user-multiple": "group",
}

/** The names offered, to the picker and to the model: one per drawing. */
export const DECK_ICON_NAMES = Object.keys(DECK_ICONS)

/** The drawing a deck's name stands for, whether its own name or an older one; `undefined` for neither. */
export function deckIconBody(name: string): string | undefined {
  const own = Object.hasOwn(DECK_ICON_ALIASES, name) ? DECK_ICON_ALIASES[name]! : name

  return Object.hasOwn(DECK_ICONS, own) ? DECK_ICONS[own] : undefined
}

/** The whole drawing for an icon a deck names, or an empty one for a name it does not know. */
export function deckIconMarkup(name: string): string {
  const body = deckIconBody(name) ?? ""

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" role="img">${body}</svg>`
}
